      ('Onsite / Văn phòng', 'Làm việc tại văn phòng'),
    ]

print('*** Begin Patch')
for path in files:
    old = open(path, encoding='utf-8').read().splitlines(True)
    new_text = ''.join(old)
    for old_s, new_s in replacements.get(path, []):
        new_text = new_text.replace(old_s, new_s)
    new = new_text.splitlines(True)
    if old == new:
        continue
    print(f'*** Update File: {path}')
    diff = list(difflib.unified_diff(old, new, n=1, lineterm=''))
    for line in diff[2:]:
        if line.startswith('@@'):
            print('@@')
        elif line.startswith((' ', '+', '-')):
            print(line)
print('*** End Patch')
