   183	    (function () {
   184	      function initJobDetailMobileBar() {
   185	        var bar = document.querySelector('.job-detail-mobile-bar');
   186	        var primaryActions = document.querySelector('.job-detail-actions, .jobs-candidate-hero-card, .job-detail-hero');
   187	        if (!bar || !primaryActions) return;
   188	
   189	        var mobileQuery = window.matchMedia('(max-width: 767px)');
   190	        var observer = null;
   191	        var fallbackListening = false;
   192	        var resizeTimer = null;
   193	        var scrollTimer = null;
   194	        var currentVisible = false;
   195	
   196	        function setBarVisible(nextVisible) {
   197	          var shouldShow = !!nextVisible;
   198	          if (currentVisible === shouldShow) return;
   199	          currentVisible = shouldShow;
   200	          bar.classList.toggle('is-visible', shouldShow);
   201	        }
   202	
   203	        function syncFallbackVisibility() {
   204	          if (!mobileQuery.matches) {
   205	            setBarVisible(false);
   206	            return;
   207	          }
   208	          var viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;
   209	          var rect = primaryActions.getBoundingClientRect();
   210	          var topSafe = 16;
   211	          var bottomSafe = 56;
   212	          var actionsInView = rect.bottom > topSafe && rect.top < (viewportHeight - bottomSafe);
   213	          setBarVisible(!actionsInView);
   214	        }
   215	
   216	        function removeFallbackListener() {
   217	          if (!fallbackListening) return;
   218	          window.removeEventListener('scroll', scheduleFallbackSync);
   219	          if (scrollTimer) {
   220	            window.clearTimeout(scrollTimer);
   221	            scrollTimer = null;
   222	          }
   223	          fallbackListening = false;
   224	        }
   225	
   226	        function setupBarObserver() {
   227	          bar.classList.add('is-managed');
   228	          if (observer) {
   229	            observer.disconnect();
   230	            observer = null;
   231	          }
   232	
   233	          if (!mobileQuery.matches) {
   234	            setBarVisible(false);
   235	            removeFallbackListener();
   236	            return;
   237	          }
   238	
   239	          if ('IntersectionObserver' in window) {
   240	            observer = new IntersectionObserver(function (entries) {
   241	              var entry = entries[0];
   242	              var ratio = entry && typeof entry.intersectionRatio === 'number' ? entry.intersectionRatio : 0;
   243	              var shouldShow = !entry || !entry.isIntersecting || ratio < 0.16;
   244	              setBarVisible(shouldShow);
   245	            }, { threshold: [0, 0.16, 0.32], rootMargin: '-6% 0px -18% 0px' });
   246	            observer.observe(primaryActions);
   247	            removeFallbackListener();
   248	            return;
   249	          }
   250	
   251	          syncFallbackVisibility();
   252	          if (!fallbackListening) {
   253	            window.addEventListener('scroll', scheduleFallbackSync, { passive: true });
   254	            fallbackListening = true;
   255	          }
   256	        }
   257	
   258	        function scheduleSetup() {
   259	          if (resizeTimer) {
   260	            window.clearTimeout(resizeTimer);
   261	          }
   262	          resizeTimer = window.setTimeout(setupBarObserver, 120);
   263	        }
   264	
   265	        function scheduleFallbackSync() {
   266	          if (!fallbackListening) return;
   267	          if (scrollTimer) return;
   268	          scrollTimer = window.setTimeout(function () {
   269	            scrollTimer = null;
   270	            syncFallbackVisibility();
   271	          }, 80);
   272	        }
   273	
   274	        setupBarObserver();
   275	        if (mobileQuery.addEventListener) {
   276	          mobileQuery.addEventListener('change', scheduleSetup);
   277	        } else if (mobileQuery.addListener) {
   278	          mobileQuery.addListener(scheduleSetup);
   279	        }
   280	        window.addEventListener('resize', scheduleSetup);
   281	      }
