   289	        var dialog = document.getElementById('candidateRequestDialog');
   290	        var triggers = Array.prototype.slice.call(document.querySelectorAll('[data-candidate-request-open]'));
   291	        if (!dialog || !triggers.length) return;
   292	
   293	        var dialogCard = dialog.querySelector('.jobs-request-dialog-card');
   294	        var closeButton = dialog.querySelector('.jobs-request-dialog-close');
   295	        var closeTargets = Array.prototype.slice.call(dialog.querySelectorAll('[data-candidate-request-close]'));
   296	
   297	        function openDialog() {
   298	          dialog.hidden = false;
   299	          document.body.classList.add('is-request-dialog-open');
   300	          if (closeButton) {
   301	            window.setTimeout(function () { closeButton.focus(); }, 10);
   302	          }
   303	        }
   304	
   305	        function closeDialog() {
   306	          if (dialog.hidden) return;
   307	          dialog.hidden = true;
   308	          document.body.classList.remove('is-request-dialog-open');
   309	        }
   310	
   311	        triggers.forEach(function (trigger) {
   312	          trigger.addEventListener('click', function (event) {
   313	            event.preventDefault();
   314	            event.stopPropagation();
   315	            openDialog();
   316	          });
   317	        });
   318	
   319	        closeTargets.forEach(function (target) {
   320	          target.addEventListener('click', function (event) {
   321	            event.preventDefault();
   322	            event.stopPropagation();
   323	            closeDialog();
   324	          });
   325	        });
   326	
   327	        dialog.addEventListener('click', function () {
   328	          closeDialog();
   329	        });
   330	
   331	        if (dialogCard) {
   332	          dialogCard.addEventListener('click', function (event) {
   333	            event.stopPropagation();
   334	          });
   335	        }
   336	
   337	        document.addEventListener('keydown', function (event) {
   338	          if (event.key === 'Escape' && !dialog.hidden) {
   339	            closeDialog();
   340	          }
   341	        });
   342	      }
   343	
   344	      document.addEventListener('DOMContentLoaded', initCandidateRequestDialog);
   345	    })();
